dtsPropsFor.Icon:
/** Which glyph. The union of the set in glyphs.ts, so a typo fails to compile. */
name: "arrow-right" | "arrow-left" | "download" | "copy" | "close-circle" | "document-text" | "check" | "chevron-down" | "chevron-right" | "menu" | "close" | "product-design" | "modernisation" | "design-systems" | "ai-product-ux" | "design-engineering" | "software-development";
/** Size role. Defaults to `md` (16). Ignored inside a control that sizes its own icons. */
size?: "sm" | "md" | "lg" | "xl";
/** An accessible name, for an icon that carries meaning ON ITS OWN. Leave it off for the
    common case — a glyph beside a label, or inside a button that already has one — where the
    icon is decorative and is rendered aria-hidden. */
label?: string;
className?: string;
